pragma solidity >=0.8.0;
contract EnvVarsProbe {
    uint256 public strictFlag;   // gasleft() > 0 at time of capture
    uint256 public originMatch;  // msg.sender == tx.origin for a direct call
    address public seenSender;
    address public seenOrigin;
    event Captured(uint256 number, uint256 gasLeft, address sender, address origin);

    function capture() external {
        strictFlag = gasleft() > 0 ? 1 : 0;
        seenSender = msg.sender;
        seenOrigin = tx.origin;
        originMatch = (msg.sender == tx.origin) ? 1 : 0;
        emit Captured(block.number, gasleft(), msg.sender, tx.origin);
    }

    function strict() external view returns (uint256) {
        return strictFlag;
    }

    function matchOrigin() external view returns (uint256) {
        return originMatch;
    }

    function originIsSender() external view returns (bool) {
        return seenOrigin == seenSender;
    }
}
